class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        @lru_cache(None)
        def dp(n: int) -> int:
            if n <= y:
                return y - n

            ans = n - y

            for d in (5, 11):
                q, r = divmod(n, d)
                ans = min(ans, r + 1 + dp(q))
                ans = min(ans, d - r + 1 + dp(q + 1))

            return ans

