    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7

        A = (a >> n) << n
        B = (b >> n) << n

        for i in range(n - 1, -1, -1):
            bit = 1 << i
            abit = (a >> i) & 1
            bbit = (b >> i) & 1

            if abit == bbit:
                A += bit
                B += bit
            else:
