from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:1 + N]

    minus_vals = [A[i] - i for i in range(N)]
    plus_vals = [A[i] + i for i in range(N)]

    def possible(k):
        left_center = k - 1
        right_center = N - k
        if left_center > right_center:
            return False

        left_min = [0] * N
        dq = deque()

        for i in range(N):
            v = minus_vals[i]
            while dq and minus_vals[dq[-1]] >= v:
                dq.pop()
            dq.append(i)

            low = i - k + 1
            while dq and dq[0] < low:
                dq.popleft()

            if i >= k - 1:
                left_min[i] = minus_vals[dq[0]]

        dq.clear()

        for i in range(N - 1, -1, -1):
            v = plus_vals[i]
            while dq and plus_vals[dq[-1]] >= v:
                dq.pop()
            dq.append(i)

            high = i + k - 1
            while dq and dq[0] > high:
                dq.popleft()

            if left_center <= i <= right_center:
                if left_min[i] >= k - i and plus_vals[dq[0]] >= k + i:
                    return True

        return False

    low = 1
    high = (N + 1) // 2

    while low < high:
        mid = (low + high + 1) // 2
        if possible(mid):
            low = mid
        else:
            high = mid - 1

    print(low)

if __name__ == "__main__":
