        n = len(word)
        INF = float("inf")

        dp = [0] * 26
        first = ord(word[0]) - ord('a')
        for c in range(26):
            dp[c] = 0 if c == first else 1

        for i in range(1, n):
            current = ord(word[i]) - ord('a')
