class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def can(k: int) -> bool:
            last = [-1] * (n + 1)
            for t in range(k):
                last[changeIndices[t]] = t

            for i in range(1, n + 1):
                if last[i] == -1:
                    return False

            spare = 0
            for t in range(k):
                idx = changeIndices[t]
                if last[idx] == t:
                    need = nums[idx - 1]
                    if spare < need:
                        return False
                    spare -= need
                else:
                    spare += 1

            return True

        if not can(m):
            return -1

        lo, hi = 1, m
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo
