from collections import Counter

class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        freq = Counter()
        for word in words:
            freq.update(word)

        pairs = sum(count // 2 for count in freq.values())
        odds = sum(count % 2 for count in freq.values())

        answer = 0
        for length in sorted(len(word) for word in words):
            needed_pairs = length // 2

            if pairs < needed_pairs:
                break

            pairs -= needed_pairs

            if length % 2 == 1:
                if odds > 0:
                    odds -= 1
                else:
                    if pairs == 0:
                        break
                    pairs -= 1
                    odds += 1

            answer += 1

        return answer
